// Local state for the Datasets tab.
//
// A dataset is rows plus ledger events (§6): creating one writes a row, adding
// a capture writes a membership, and NOTHING moves on disk. So this hook does
// not orchestrate an export — it reads two lists (`GET /datasets`,
// `GET /captures`), joins the memberships the capture list already carries, and
// sends the four mutations §6 defines. The browsable `views/` tree is
// regenerated by the server after each of those mutations; there is deliberately
// no refresh call here, because a second writer racing the one owner is how a
// symlink tree ends up disagreeing with the catalog.
//
// The addressable slice of this state (both searches, the facets, the sort, the
// selected dataset + member) is seeded from the query string on mount and
// mirrored back into it on every change, so a view is shareable, survives a
// reload, and survives a tab round-trip — the shell unmounts this screen on a
// tab switch, which would otherwise discard everything. See url.ts for the key
// contract; `replaceState` (not push) keeps a keystroke-by-keystroke search out
// of the browser's history.
//
// Both selections are stored as IDENTITY (dataset_id, membership_id) and then
// DERIVED from the freshly loaded data. That is what lets a deep link restore a
// selection before the lists have finished loading, and what makes a removed
// member degrade to "nothing selected" instead of leaving a destructive control
// pointed at a row that is no longer on screen.

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { apiGet } from '../../api/client';
import {
  addDatasetMember,
  archiveCapture,
  archiveDataset,
  createDataset,
  deleteDataset,
  getArchiveConfig,
  getCapture,
  getDataset,
  getDatasetArchive,
  listAllCaptures,
  listDatasets,
  removeDatasetMember,
  updateDataset,
} from '../../api/captures';
import { queryKeys } from '../../api/queryKeys';
import type {
  Capture,
  CaptureDetail,
  DatasetArchiveProgress,
} from '../../api/types';
import { availabilityOf } from '../captures/availability';
import {
  captureErrorText,
  isDestructiveFailure,
  readCaptureError,
} from '../captures/errors';
import { useCaptureDeletion, type CaptureDeletionState } from '../captures/useCaptureDeletion';
import {
  ANY_OPERATOR,
  MEMBER_PAGE_SIZE,
  addBlockedReason,
  aggregate,
  buildDatasetRows,
  datasetMatchesSearch,
  distinctOperators,
  filterMembers,
  findDataset,
  indexCaptures,
  joinMembers,
  membersByDataset,
  type DatasetAggregate,
  type DatasetRow,
  type MemberRow,
  type SortMode,
  type TaskResultFilter,
} from './data';
import { readDatasetsUrl, writeDatasetsUrl } from './url';

export type { TaskResultFilter } from './data';

/** This screen's own capture sweep: the whole catalog, because a dataset may
 *  cite any capture in it and the "add a capture" picker offers from all of it.
 *  A different shape from any per-page list, so it gets its own cache entry. */
const CAPTURE_SCOPE = 'datasets';

/** Capture states that may be added to a dataset: a recording that has finished,
 *  one way or another. A live recording has no final bytes to cite, and a
 *  tombstone (§7) has none left. */
const ADDABLE_STATES = new Set(['completed', 'failed', 'interrupted']);

/** How many candidate captures the rail builds at once. The rest are reachable
 *  by narrowing the search — the boundary is stated, never silent. */
const CANDIDATE_LIMIT = 50;

/** The scope the center's summary describes: the selected dataset, or — when
 *  none is selected — every member of every dataset in view. */
export interface ScopeSummary {
  kind: 'dataset' | 'catalog';
  /** Header label (the dataset's name, or "All datasets"). */
  label: string;
  operator: string | null;
  task: string | null;
  aggregate: DatasetAggregate;
  /** Members the aggregate could say nothing about (§ see DatasetRow). */
  unresolved: number;
}

export interface DatasetsState {
  /** The dataset rows the left column renders (search-filtered, sorted). */
  rows: DatasetRow[];
  /** Datasets surviving the search. */
  shown: number;
  /** Datasets before filtering (to say "showing n of m" honestly). */
  total: number;

  search: string;
  setSearch: (s: string) => void;
  sort: SortMode;
  toggleSort: () => void;

  /** 'active' (default) = the working sets; 'archived' = the sealed record.
   *  Archived datasets appear ONLY under their own view. */
  datasetView: 'active' | 'archived';
  setDatasetView: (v: 'active' | 'archived') => void;
  activeDatasetCount: number;
  archivedDatasetCount: number;

  taskResultFilter: TaskResultFilter;
  setTaskResultFilter: (f: TaskResultFilter) => void;
  operatorFilter: string;
  setOperatorFilter: (o: string) => void;
  /** Distinct operators across the loaded captures (facet choices). */
  operatorOptions: string[];
  /** The capture sweep hit its page cap, so everything derived from it
   *  describes PART of the catalog. Nothing on screen may read as complete
   *  while this is true. */
  catalogTruncated: boolean;

  // ---- dataset selection -------------------------------------------------
  selectedDatasetId: string | null;
  selectedDataset: DatasetRow | null;
  /** A dataset's name for its dataset_id, or null when the loaded catalog has
   *  no row for it. The archive refusals name the dataset holding a
   *  destination by ID only, and an id alone is not something an operator
   *  recognises — this is what lets a dialog show both. */
  datasetName: (datasetId: string) => string | null;
  /** The selected dataset is not in the server's list any more — it was deleted
   *  outside this screen. Distinct from "no selection" and from "hidden by the
   *  search": both of those leave a live dataset behind, and this one does not,
   *  so every destructive control aimed at it has to stand down and say why. */
  selectionGone: boolean;
  selectDataset: (datasetId: string) => void;
  isDatasetSelected: (datasetId: string) => boolean;
  clearDataset: () => void;

  // ---- creating a dataset (§6: a row, nothing on disk) -------------------
  createOpen: boolean;
  openCreate: () => void;
  cancelCreate: () => void;
  newName: string;
  setNewName: (s: string) => void;
  newOperator: string;
  setNewOperator: (s: string) => void;
  newTask: string;
  setNewTask: (s: string) => void;
  submitCreate: () => void;
  creating: boolean;
  createError: unknown;

  // ---- editing the labels (identity is dataset_id; names move) -----------
  /** The selected dataset's labels may be edited right now (active only). */
  canEditDataset: boolean;
  editOpen: boolean;
  openEdit: () => void;
  cancelEdit: () => void;
  editName: string;
  setEditName: (s: string) => void;
  editOperator: string;
  setEditOperator: (s: string) => void;
  editTask: string;
  setEditTask: (s: string) => void;
  submitEdit: () => void;
  editing: boolean;
  editError: unknown;

  // ---- combining datasets (a new set from existing ones; sources stay) ----
  combineOpen: boolean;
  openCombine: () => void;
  cancelCombine: () => void;
  /** Active datasets offered as sources (with their member counts). */
  combineChoices: { datasetId: string; name: string; memberCount: number }[];
  /** Selected sources, in selection order — the order members are numbered. */
  combineSources: string[];
  toggleCombineSource: (datasetId: string) => void;
  combineName: string;
  setCombineName: (s: string) => void;
  combineOperator: string;
  setCombineOperator: (s: string) => void;
  combineTask: string;
  setCombineTask: (s: string) => void;
  submitCombine: () => void;
  combineBusy: boolean;
  combineDone: number;
  combineTotal: number;
  /** Per-capture failures, reported honestly; the dialog stays open on any. */
  combineFailures: { captureId: string; message: string }[];
  combineError: unknown;

  // ---- deleting a dataset (rows only; no capture is touched) -------------
  confirmingDatasetDelete: boolean;
  requestDatasetDelete: () => void;
  cancelDatasetDelete: () => void;
  confirmDatasetDelete: () => void;
  deletingDataset: boolean;
  datasetDeleteError: unknown;

  // ---- members -----------------------------------------------------------
  /** Member-row search inside the center pane (distinct from the list search). */
  memberSearch: string;
  setMemberSearch: (s: string) => void;
  /** Every member in the current scope after the facets — the denominator for
   *  "n of m" in the center pane. */
  scopeMembers: MemberRow[];
  /** scopeMembers narrowed by memberSearch and CAPPED at one page — the rows
   *  actually built into the DOM. */
  memberRows: MemberRow[];
  /** How many members match in the scope before the page cap. */
  memberMatchCount: number;
  page: number;
  pageCount: number;
  pageSize: number;
  goToPage: (page: number) => void;
  scope: ScopeSummary;

  // Member selection. selectMember TOGGLES: clicking the already-selected row
  // (or the summary row) clears it and returns to the summary.
  selected: MemberRow | null;
  selectMember: (row: MemberRow) => void;
  isMemberSelected: (row: MemberRow) => boolean;
  selectSummary: () => void;
  /** True when no member is selected — the bottom pane shows the scope summary. */
  isSummaryActive: boolean;

  /** The selected member's capture, with its sidecars. */
  detail: CaptureDetail | null;
  detailLoading: boolean;
  detailError: boolean;

  removeMember: (row: MemberRow) => void;
  /** membership_id currently being removed, or null. */
  removingMembershipId: string | null;

  // ---- adding a capture --------------------------------------------------
  /** Finished captures not already in the selected dataset, newest first and
   *  capped at CANDIDATE_LIMIT. */
  candidates: Capture[];
  /** How many matched before the cap, so the rail can say what it is not
   *  showing. */
  candidateMatchCount: number;
  candidateSearch: string;
  setCandidateSearch: (s: string) => void;
  addMember: (capture: Capture) => void;
  addingCaptureId: string | null;
  /** Candidates that cannot join today (not adopted / bytes elsewhere) are
   *  hidden by default; the count is always stated and this reveals them. */
  showBlockedCandidates: boolean;
  toggleBlockedCandidates: () => void;
  blockedCandidateCount: number;

  // ---- removing the bytes (§7, via the shared dialogs) -------------------
  deletion: CaptureDeletionState;
  /** True on a split deployment, so the discard dialog says — unprompted — that
   *  a copy may still exist on the robot (§12). */
  splitDeploy: boolean;

  // ---- archive (§6: per capture, and NOT a job) --------------------------
  // Copies a capture out, verifies it, then removes the source. `archiveEnabled`
  // is false when the deployment configured no roots — the control is then not
  // rendered at all, because it could only ever fail.
  archiveEnabled: boolean;
  archiveRoots: string[];
  /** True when this capture may be archived at all: the backend refuses a
   *  capture that is still in any dataset, exactly as it refuses a delete. */
  canArchive: (capture: Capture) => boolean;
  archiveTarget: Capture | null;
  openArchive: (capture: Capture) => void;
  cancelArchive: () => void;
  archiveRoot: string;
  setArchiveRoot: (root: string) => void;
  archiveSubpath: string;
  setArchiveSubpath: (path: string) => void;
  /** The destination sent to the server. The server appends the capture id
   *  under it, so this is the PARENT of what lands on disk. */
  archiveDestination: string;
  /** Where the files actually land — `<destination>/<capture_id>`. */
  archiveFinalPath: string;
  archiveReason: string;
  setArchiveReason: (s: string) => void;
  confirmArchive: () => void;
  archiving: boolean;
  archiveError: unknown;

  // ---- dataset archive (§6.x: the terminal transition) --------------------
  // Copy the WHOLE dataset out — views shape plus a manifest — verify every
  // file, then remove the members from this machine. Terminal: the dataset's
  // member set freezes at the start and its status never returns to active.
  /** status ≠ 'active' — the dataset's member set is frozen (§6.x). */
  isDatasetFrozen: (datasetId: string) => boolean;
  /** The selected dataset may start an archive run right now. */
  canArchiveDataset: boolean;
  datasetArchiveOpen: boolean;
  openDatasetArchive: () => void;
  cancelDatasetArchive: () => void;
  datasetArchiveRoot: string;
  setDatasetArchiveRoot: (root: string) => void;
  /** The dataset's folder path under the root — the operator's to edit,
   *  prefilled with the views shape `<operator>/<task>/<name>`. */
  datasetArchivePath: string;
  setDatasetArchivePath: (path: string) => void;
  /** The allow-listed root sent as `destination`. */
  datasetArchiveDestination: string;
  /** Where the dataset actually lands: `<root>/<path>`. */
  datasetArchiveFinalDir: string;
  datasetArchiveReason: string;
  setDatasetArchiveReason: (s: string) => void;
  /** 'copy' seals and keeps the recordings; 'move' removes them (exclusive
   *  members only — the server refuses shared ones). */
  datasetArchiveMode: 'copy' | 'move';
  setDatasetArchiveMode: (m: 'copy' | 'move') => void;
  /** Members that also belong to another active dataset — what makes Move
   *  refuse and Copy the natural pick (a combined set). */
  datasetArchiveSharedCount: number;
  confirmDatasetArchive: () => void;
  /** Re-POST with no destination: continue a halted run where it stood. */
  resumeDatasetArchive: () => void;
  datasetArchiveStarting: boolean;
  datasetArchiveStartError: unknown;
  /** Live progress while the selected dataset is archiving (1 s poll). */
  datasetArchiveProgress: DatasetArchiveProgress | null;

  isLoading: boolean;
  isError: boolean;

  toast: string;
  /** A `destructive`-severity failure, held until the operator dismisses it.
   *  §12 reserves that severity for what must not pass as a note that fades;
   *  the toast keeps the ordinary refusals. */
  blockingFailure: unknown;
  dismissBlockingFailure: () => void;
}

/** Milliseconds a search box may keep typing before the lists are refiltered.
 *  Long enough to swallow a fast typist's keystrokes, short enough that a pause
 *  reads as "it kept up" rather than "it is thinking". */
const SEARCH_DEBOUNCE_MS = 150;

/** *value*, but only after it has stopped changing for *delay* ms. */
function useDebounced<T>(value: T, delay: number): T {
  const [settled, setSettled] = useState(value);
  useEffect(() => {
    const timer = setTimeout(() => setSettled(value), delay);
    return () => clearTimeout(timer);
  }, [value, delay]);
  return settled;
}

const TOAST_MS = 2400;

/** A server sentence, terminated, so ours can follow it without fusing.
 *
 *  The store is not consistent about a trailing period — "No member m-2 in
 *  dataset ds-kitchen." has one, "Dataset not found: ds-kitchen" does not — and
 *  appending to the second produced "…ds-kitchen The member list has been
 *  reloaded…": one broken sentence, which costs the whole line its credibility.
 *  Ellipsis and dashes are left alone; they are already a legible ending. */
function terminated(text: string): string {
  const trimmed = text.trim();
  if (!trimmed) return '';
  return /[.!?…—:]$/.test(trimmed) ? trimmed : `${trimmed}.`;
}

/** Case-insensitive substring match over a capture's own identifying fields —
 *  the candidate picker's find. */
function captureMatches(capture: Capture, query: string): boolean {
  const q = query.trim().toLowerCase();
  if (!q) return true;
  return [capture.capture_id, capture.run_id, capture.operator, capture.task]
    .filter((v): v is string => typeof v === 'string' && v !== '')
    .some((v) => v.toLowerCase().includes(q));
}

export function useDatasetsState(): DatasetsState {
  const queryClient = useQueryClient();
  // Seed every addressable field from the query string ONCE — this is what a
  // deep link, a reload, and a return to the tab (the shell unmounts this
  // screen on a tab switch) all restore from.
  const [seed] = useState(() => readDatasetsUrl(window.location.search));

  const [selectedDatasetId, setSelectedDatasetId] = useState<string | null>(seed.datasetId);
  const [selectedMembershipId, setSelectedMembershipId] = useState<string | null>(
    seed.membershipId,
  );
  const [search, setSearch] = useState(seed.search);
  const [memberSearch, setMemberSearch] = useState(seed.memberSearch);
  const [sort, setSort] = useState<SortMode>(seed.sort);
  const [taskResultFilter, setTaskResultFilter] = useState<TaskResultFilter>(
    seed.taskResultFilter,
  );
  const [datasetView, setDatasetView] = useState<'active' | 'archived'>(seed.view);
  const [operatorFilter, setOperatorFilter] = useState<string>(seed.operatorFilter);
  const [page, setPage] = useState(1);

  const [createOpen, setCreateOpen] = useState(false);
  const [newName, setNewName] = useState('');
  const [newOperator, setNewOperator] = useState('');
  const [newTask, setNewTask] = useState('');
  const [confirmingDatasetDelete, setConfirmingDatasetDelete] = useState(false);
  const [editOpen, setEditOpen] = useState(false);
  const [editName, setEditName] = useState('');
  const [editOperator, setEditOperator] = useState('');
  const [editTask, setEditTask] = useState('');
  const [combineOpen, setCombineOpen] = useState(false);
  const [combineName, setCombineName] = useState('');
  const [combineOperator, setCombineOperator] = useState('');
  const [combineTask, setCombineTask] = useState('');
  const [combineSources, setCombineSources] = useState<string[]>([]);
  const [combineBusy, setCombineBusy] = useState(false);
  const [combineDone, setCombineDone] = useState(0);
  const [combineTotal, setCombineTotal] = useState(0);
  const [combineFailures, setCombineFailures] = useState<
    { captureId: string; message: string }[]
  >([]);
  const [combineError, setCombineError] = useState<unknown>(null);
  const [candidateSearch, setCandidateSearch] = useState('');
  const [showBlockedCandidates, setShowBlockedCandidates] = useState(false);
  const [archiveTarget, setArchiveTarget] = useState<Capture | null>(null);
  const [archiveRoot, setArchiveRoot] = useState('');
  const [archiveSubpath, setArchiveSubpath] = useState('');
  const [archiveReason, setArchiveReason] = useState('');
  const [datasetArchiveOpen, setDatasetArchiveOpen] = useState(false);
  const [datasetArchiveRoot, setDatasetArchiveRoot] = useState('');
  const [datasetArchivePath, setDatasetArchivePath] = useState('');
  const [datasetArchiveReason, setDatasetArchiveReason] = useState('');
  const [datasetArchiveMode, setDatasetArchiveMode] = useState<'copy' | 'move'>('move');
  const [toast, setToast] = useState('');
  const [blockingFailure, setBlockingFailure] = useState<unknown>(null);
  const toastTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const showToast = useCallback((message: string) => {
    if (toastTimerRef.current) clearTimeout(toastTimerRef.current);
    setToast(message);
    toastTimerRef.current = setTimeout(() => setToast(''), TOAST_MS);
  }, []);

  useEffect(
    () => () => {
      if (toastTimerRef.current) clearTimeout(toastTimerRef.current);
    },
    [],
  );

  // Where a refusal goes is the catalog's call, not each call site's: anything
  // errors.ts marks `destructive` is held until dismissed, everything else
  // keeps the toast. Reading severity rather than listing codes means a code
  // added later arrives with the right treatment already.
  const reportFailure = useCallback(
    (error: unknown) => {
      if (isDestructiveFailure(error)) {
        if (toastTimerRef.current) clearTimeout(toastTimerRef.current);
        setToast('');
        setBlockingFailure(error);
        return;
      }
      showToast(captureErrorText(error));
    },
    [showToast],
  );

  // ---- reads -------------------------------------------------------------

  const listQuery = useQuery({
    queryKey: queryKeys.datasets,
    queryFn: ({ signal }) => listDatasets(signal),
  });
  const datasets = useMemo(() => listQuery.data?.items ?? [], [listQuery.data]);

  // This screen is not the only writer: another operator, a curl, a rebuild.
  // The dataset LIST is the authority on existence, so a selection that is not
  // in a freshly loaded list was deleted somewhere else — and the screen has to
  // say that rather than fall back to its ordinary "pick a dataset" prompt,
  // which the operator reads as their own click having been lost. Gated on a
  // loaded list: "absent from a list we have not fetched yet" is evidence of
  // nothing, and a search that merely HIDES the row leaves it here.
  const selectionGone =
    selectedDatasetId !== null &&
    listQuery.isSuccess &&
    !datasets.some((d) => d.dataset_id === selectedDatasetId);

  const capturesQuery = useQuery({
    queryKey: queryKeys.captureList(CAPTURE_SCOPE),
    queryFn: ({ signal }) => listAllCaptures({}, signal),
  });
  const captures = useMemo(() => capturesQuery.data?.items ?? [], [capturesQuery.data]);
  // `listAllCaptures` follows the cursor for at most MAX_PAGES and then stops,
  // returning what it has WITH the unfinished cursor — so a non-null cursor
  // here means the sweep did not reach the end of the catalog. The signal was
  // already in the response and every consumer threw it away, which is how a
  // rail that lists 10,000 of 12,000 recordings ends as quietly as one that
  // lists all of them (E-27).
  const catalogTruncated = capturesQuery.data?.next_cursor != null;
  const capturesById = useMemo(() => indexCaptures(captures), [captures]);

  // The selected dataset's members come from its own endpoint rather than from
  // the memberships on the captures: it is the authority on what belongs to it,
  // and it still lists a member whose capture never reached this host — which
  // the capture-side join structurally cannot.
  const detailQuery = useQuery({
    queryKey: queryKeys.dataset(selectedDatasetId ?? ''),
    queryFn: ({ signal }) => getDataset(selectedDatasetId ?? '', signal),
    // Once the list has said the dataset is gone, asking for its detail can only
    // 404 on every refetch from here on.
    enabled: selectedDatasetId !== null && !selectionGone,
  });

  const debouncedSearch = useDebounced(search, SEARCH_DEBOUNCE_MS);
  const debouncedMemberSearch = useDebounced(memberSearch, SEARCH_DEBOUNCE_MS);
  const debouncedCandidateSearch = useDebounced(candidateSearch, SEARCH_DEBOUNCE_MS);

  const membersByDatasetId = useMemo(() => membersByDataset(captures), [captures]);
  // The list shows one shelf at a time: the working sets by default, the
  // sealed record only when asked for. An archiving run still belongs to the
  // working shelf — it is a set in motion, not history yet.
  const viewDatasets = useMemo(
    () =>
      datasets.filter((d) =>
        datasetView === 'archived' ? d.status === 'archived' : d.status !== 'archived',
      ),
    [datasets, datasetView],
  );
  const allRows = useMemo(
    () => buildDatasetRows(viewDatasets, membersByDatasetId, sort),
    [viewDatasets, membersByDatasetId, sort],
  );
  const rows = useMemo(
    () => allRows.filter((row) => datasetMatchesSearch(row, debouncedSearch)),
    [allRows, debouncedSearch],
  );

  // The selected dataset is DERIVED from the loaded list, so a search that hides
  // it — or a deletion that removed it — degrades to "nothing selected" rather
  // than leaving stale rows and a live Delete on screen.
  const selectedRow = useMemo(
    () => findDataset(rows, selectedDatasetId),
    [rows, selectedDatasetId],
  );

  const operatorOptions = useMemo(() => distinctOperators(captures), [captures]);

  // Scope members: the selected dataset's authoritative member list joined to
  // the captures, else every member of every dataset in view.
  const scopeAllMembers = useMemo(() => {
    if (selectedRow) {
      const members = detailQuery.data?.members;
      // Until the detail lands, the capture-side join is what we honestly have.
      return members ? joinMembers(members, capturesById) : selectedRow.members;
    }
    // Nothing selected = nothing listed. The old whole-catalog scope mixed
    // every dataset's numbering into one table, where #N meant nothing.
    return [];
  }, [selectedRow, detailQuery.data, capturesById]);

  const scopeMembers = useMemo(
    () =>
      filterMembers(scopeAllMembers, {
        search: '',
        taskResultFilter,
        operatorFilter,
      }),
    [scopeAllMembers, taskResultFilter, operatorFilter],
  );

  const matchedMembers = useMemo(
    () =>
      filterMembers(scopeMembers, {
        search: debouncedMemberSearch,
        taskResultFilter: 'all',
        operatorFilter: ANY_OPERATOR,
      }),
    [scopeMembers, debouncedMemberSearch],
  );

  const scopeAggregate = useMemo(() => aggregate(scopeMembers), [scopeMembers]);
  const scope: ScopeSummary = useMemo(() => {
    if (selectedRow) {
      return {
        kind: 'dataset',
        label: selectedRow.dataset.name,
        operator: selectedRow.dataset.operator ?? null,
        task: selectedRow.dataset.task ?? null,
        aggregate: scopeAggregate,
        unresolved: selectedRow.unresolved,
      };
    }
    return {
      kind: 'catalog',
      label: 'All datasets',
      operator: null,
      task: null,
      aggregate: scopeAggregate,
      unresolved: rows.reduce((sum, row) => sum + row.unresolved, 0),
    };
  }, [selectedRow, scopeAggregate, rows]);

  const pageCount = Math.max(1, Math.ceil(matchedMembers.length / MEMBER_PAGE_SIZE));
  // Anything that changes WHICH members are on screen returns to page one —
  // page 4 of a dataset that no longer has 800 members is an empty table, and
  // the operator did not ask to go there.
  useEffect(() => {
    setPage(1);
  }, [selectedDatasetId, debouncedMemberSearch, debouncedSearch, taskResultFilter, operatorFilter]);
  // Clamp rather than trust: a page can fall out of range when rows disappear
  // under an already-open view (a removal, a refetch), and reading past the end
  // must never render a blank table.
  const currentPage = Math.min(Math.max(1, page), pageCount);
  const memberRows = useMemo(
    () =>
      matchedMembers.slice(
        (currentPage - 1) * MEMBER_PAGE_SIZE,
        currentPage * MEMBER_PAGE_SIZE,
      ),
    [matchedMembers, currentPage],
  );

  // The selected MEMBER is derived for a sharper reason than stale rows: the
  // detail pane carries live Remove and Delete controls. A filter must never
  // leave a destructive control pointed at an off-screen target.
  const selected = useMemo(
    () => scopeMembers.find((row) => row.membershipId === selectedMembershipId) ?? null,
    [scopeMembers, selectedMembershipId],
  );

  const captureDetailQuery = useQuery({
    queryKey: queryKeys.capture(selected?.captureId ?? ''),
    queryFn: ({ signal }) => getCapture(selected?.captureId ?? '', signal),
    enabled: selected?.captureId !== undefined && selected?.capture !== null,
  });

  // ---- selection ---------------------------------------------------------

  const selectDataset = useCallback((datasetId: string) => {
    setSelectedDatasetId(datasetId);
    setSelectedMembershipId(null); // switching datasets clears the member selection
    setMemberSearch(''); // and its one-shot find
  }, []);
  const clearDataset = useCallback(() => {
    setSelectedDatasetId(null);
    setSelectedMembershipId(null);
  }, []);
  const selectMember = useCallback((row: MemberRow) => {
    setSelectedMembershipId((cur) => (cur === row.membershipId ? null : row.membershipId));
  }, []);
  const selectSummary = useCallback(() => setSelectedMembershipId(null), []);

  const toggleSort = useCallback(
    () => setSort((s) => (s === 'recent' ? 'alpha' : 'recent')),
    [],
  );

  // Mirror the addressable state back into the query string, so the view is
  // shareable, survives a reload, and is still there after a tab round-trip.
  // `replaceState` (not push) — a search box typed character by character must
  // not fill the history stack. `tab` / `solo` are carried through untouched:
  // they belong to the shell, which likewise rebuilds the query string from
  // window.location.search and so preserves these keys in return.
  //
  // Both selections are written from the STORED identity rather than the
  // resolved row, so a deep link isn't erased by the lists still loading.
  useEffect(() => {
    const current = window.location.search;
    const next = writeDatasetsUrl(current, {
      search,
      memberSearch,
      sort,
      taskResultFilter,
      operatorFilter,
      view: datasetView,
      datasetId: selectedDatasetId,
      membershipId: selectedMembershipId,
    });
    if (next === current.replace(/^\?/, '')) return;
    window.history.replaceState(
      null,
      '',
      next ? `${window.location.pathname}?${next}` : window.location.pathname,
    );
  }, [
    search,
    memberSearch,
    sort,
    taskResultFilter,
    operatorFilter,
    datasetView,
    selectedDatasetId,
    selectedMembershipId,
  ]);

  // ---- mutations ---------------------------------------------------------

  const invalidateDatasets = useCallback(
    async (datasetId?: string | null) => {
      await queryClient.invalidateQueries({ queryKey: queryKeys.datasets });
      await queryClient.invalidateQueries({ queryKey: queryKeys.captures });
      if (datasetId) {
        await queryClient.invalidateQueries({ queryKey: queryKeys.dataset(datasetId) });
      }
    },
    [queryClient],
  );

  const createMutation = useMutation({
    mutationFn: () =>
      createDataset({
        name: newName.trim(),
        operator: newOperator.trim() || null,
        task: newTask.trim() || null,
      }),
    onSuccess: async (dataset) => {
      await invalidateDatasets(dataset.dataset_id);
      setCreateOpen(false);
      setNewName('');
      setNewOperator('');
      setNewTask('');
      setSelectedDatasetId(dataset.dataset_id);
      setSelectedMembershipId(null);
      showToast(`Created “${dataset.name}” — nothing was written under objects/`);
    },
  });

  const deleteDatasetMutation = useMutation({
    mutationFn: (datasetId: string) => deleteDataset(datasetId),
    onSuccess: async (_res, datasetId) => {
      queryClient.removeQueries({ queryKey: queryKeys.dataset(datasetId) });
      // Drop the selection BEFORE the list reloads without it, or the refetch
      // lands on a still-selected id and the screen flashes "this dataset is
      // gone" at the operator who just deleted it on purpose.
      setConfirmingDatasetDelete(false);
      clearDataset();
      await invalidateDatasets();
      showToast('Dataset deleted — every recording it listed is untouched');
    },
    // A refused delete is a statement about the store, not just about this
    // click: 404 means someone else already deleted it, 409 that it archived
    // underneath us. Reload so the rest of the screen stops asserting the old
    // shape; the dialog keeps the error and says what it now knows.
    onError: () => void invalidateDatasets(),
  });

  const addMutation = useMutation({
    mutationFn: (capture: Capture) =>
      addDatasetMember(selectedDatasetId ?? '', capture.capture_id),
    onSuccess: async (member) => {
      await invalidateDatasets(member.dataset_id);
      showToast(`Added as #${member.display_index} — the recording did not move`);
    },
    onError: reportFailure,
  });

  const removeMutation = useMutation({
    mutationFn: (row: MemberRow) => removeDatasetMember(row.datasetId, row.membershipId),
    onSuccess: async (_res, row) => {
      await invalidateDatasets(row.datasetId);
      if (selectedMembershipId === row.membershipId) setSelectedMembershipId(null);
      showToast(
        `Removed #${row.displayIndex} — the recording is untouched and the ` +
          'number is not reused',
      );
    },
    // The row we aimed at may already be gone (another operator, a curl). Left
    // alone, the failure would leave that row on screen with a live Remove on
    // it — a control that can now only fail again. So reload, and say the
    // server's own words rather than the stock "reload the dataset" guidance:
    // telling the operator to do what the screen just did is not honesty.
    onError: async (error, row) => {
      await invalidateDatasets(row.datasetId);
      const reading = readCaptureError(error);
      showToast(
        reading.reload
          ? `${terminated(reading.message)} The member list has been reloaded ` +
              'from the server.'
          : captureErrorText(error),
      );
    },
  });

  // §12 obliges the discard dialog to say that a copy may remain on the robot —
  // but only where that is true. The pull channel's health check answers on a
  // split recording-PC deploy and nowhere else, so its availability IS "this is
  // a split deployment". Read once per session, on the key Review uses, so the
  // two screens share one probe and cannot disagree about the deployment they
  // are running on. On error the default (off) stands honestly.
  const transferStatusQuery = useQuery({
    queryKey: queryKeys.transferStatus,
    queryFn: ({ signal }) => apiGet<{ available?: boolean }>('/transfer/status', { signal }),
    staleTime: Infinity,
    refetchOnWindowFocus: false,
    retry: false,
  });

  const deletion = useCaptureDeletion({
    invalidate: useMemo(
      () =>
        selectedDatasetId
          ? [queryKeys.datasets, queryKeys.dataset(selectedDatasetId)]
          : [queryKeys.datasets],
      [selectedDatasetId],
    ),
    onDeleted: useCallback(() => setSelectedMembershipId(null), []),
    onToast: showToast,
  });

  // ---- archive -----------------------------------------------------------

  // Capability first: with no roots configured the archive control never renders
  // (do not offer what cannot run). The probe is addressed to a capture because
  // that is the route's shape, but it answers for the DEPLOYMENT — the handler
  // reads KAIROS_ARCHIVE_ROOTS and nothing about the capture — so one probe
  // governs every control on this screen.
  const probeCaptureId = captures[0]?.capture_id ?? null;
  const archiveConfigQuery = useQuery({
    queryKey: queryKeys.archiveConfig,
    queryFn: ({ signal }) => getArchiveConfig(probeCaptureId ?? '', signal),
    enabled: probeCaptureId !== null,
  });
  const archiveRoots = useMemo(
    () => archiveConfigQuery.data?.roots ?? [],
    [archiveConfigQuery.data],
  );
  const archiveEnabled = (archiveConfigQuery.data?.enabled ?? false) && archiveRoots.length > 0;

  // The backend refuses to archive a capture that still belongs to a dataset,
  // for the same reason it refuses to delete one: the dataset would be left
  // citing something that is no longer here. Offering the control anyway would
  // be offering a guaranteed failure.
  const canArchive = useCallback(
    (capture: Capture) =>
      archiveEnabled &&
      (capture.memberships ?? []).length === 0 &&
      availabilityOf(capture).usable,
    [archiveEnabled],
  );

  const effectiveRoot = archiveRoot || archiveRoots[0] || '';
  // Default subpath from the capture's OWN operator/task, and only those it
  // actually records — an archive tree then reads the way the catalog does,
  // without inventing an "unknown" folder for a capture that names neither.
  const defaultSubpath = archiveTarget
    ? [archiveTarget.operator, archiveTarget.task].filter(Boolean).join('/')
    : '';
  const subpath = archiveSubpath || defaultSubpath;
  const archiveDestination = effectiveRoot
    ? `${effectiveRoot.replace(/\/+$/, '')}${subpath ? `/${subpath.replace(/^\/+/, '')}` : ''}`
    : '';
  // The server writes into `<destination>/<capture_id>`, so the destination the
  // operator types is the PARENT. Both are shown; guessing which one is meant
  // is how an archive lands one level off.
  const archiveFinalPath =
    archiveDestination && archiveTarget
      ? `${archiveDestination}/${archiveTarget.capture_id}`
      : '';

  const archiveMutation = useMutation({
    mutationFn: (capture: Capture) =>
      archiveCapture(capture.capture_id, {
        destination: archiveDestination,
        operator: capture.operator ?? null,
        reason: archiveReason.trim() || null,
      }),
    onSuccess: async (res) => {
      await invalidateDatasets(selectedDatasetId);
      setArchiveTarget(null);
      setArchiveSubpath('');
      setArchiveReason('');
      showToast(
        res.verified
          ? `Archived to ${res.destination} — verified, then removed from this machine`
          : `Copied to ${res.destination}, but it did NOT verify — check it before ` +
              'trusting the copy',
      );
    },
  });

  const openArchive = useCallback((capture: Capture) => {
    setArchiveTarget(capture);
    setArchiveSubpath('');
    setArchiveReason('');
  }, []);
  const cancelArchive = useCallback(() => setArchiveTarget(null), []);

  // ---- label edits (identity is dataset_id; names move) -------------------

  const editMutation = useMutation({
    mutationFn: () =>
      updateDataset(selectedDatasetId ?? '', {
        name: editName.trim(),
        // Empty in the form means "no label", said as an explicit null —
        // omitting the key would mean "keep", which is a different statement.
        operator: editOperator.trim() || null,
        task: editTask.trim() || null,
      }),
    onSuccess: async (dataset) => {
      await invalidateDatasets(dataset.dataset_id);
      setEditOpen(false);
      showToast(
        `Renamed to “${dataset.name}” — same dataset, same members, same numbers`,
      );
    },
    // A rename is not destructive, but it is aimed at the same row the other
    // three dialogs are, and it fails the same way when that row is gone (404)
    // or frozen (409). Reload for the same reason they do — the dialog keeps
    // the error and then says what the refetch taught it.
    onError: () => void invalidateDatasets(),
  });

  // ---- combining datasets -------------------------------------------------

  // A combine is ordinary building done in bulk: create a new dataset, then
  // add every member of every source through the same POST the rail uses —
  // sequentially, with progress, failures reported per capture (the standing
  // bulk rule). The sources are never written to; a dataset is a list, and
  // reading a list does not change it.
  const submitCombine = async () => {
    if (combineBusy || !combineName.trim() || combineSources.length === 0) return;
    setCombineBusy(true);
    setCombineError(null);
    setCombineFailures([]);
    setCombineDone(0);
    setCombineTotal(0);
    try {
      // Read every source first: the total is known before the first add, so
      // the progress can say n of m instead of counting into the unknown.
      const sourceDetails = [];
      for (const id of combineSources) {
        sourceDetails.push(await getDataset(id));
      }
      const seen = new Set<string>();
      const captureIds: string[] = [];
      for (const detail of sourceDetails) {
        for (const member of [...detail.members].sort(
          (a, b) => a.display_index - b.display_index,
        )) {
          // A capture in two sources joins once — the new set numbers it at
          // its first appearance.
          if (seen.has(member.capture_id)) continue;
          seen.add(member.capture_id);
          captureIds.push(member.capture_id);
        }
      }
      setCombineTotal(captureIds.length);

      const created = await createDataset({
        name: combineName.trim(),
        operator: combineOperator.trim() || null,
        task: combineTask.trim() || null,
      });
      const failures: { captureId: string; message: string }[] = [];
      for (const captureId of captureIds) {
        try {
          await addDatasetMember(created.dataset_id, captureId);
        } catch (error) {
          failures.push({ captureId, message: captureErrorText(error) });
          setCombineFailures([...failures]);
        }
        setCombineDone((done) => done + 1);
      }
      await invalidateDatasets(created.dataset_id);
      setSelectedDatasetId(created.dataset_id);
      setSelectedMembershipId(null);
      if (failures.length === 0) {
        setCombineOpen(false);
        setCombineSources([]);
        setCombineName('');
        setCombineOperator('');
        setCombineTask('');
        showToast(
          `Combined ${captureIds.length} recording${captureIds.length === 1 ? '' : 's'} ` +
            `into “${created.name}” — the source datasets are untouched`,
        );
      }
      // With failures the dialog stays open: the list of what did not join is
      // the result, and a toast would swallow it.
    } catch (error) {
      setCombineError(error);
    } finally {
      setCombineBusy(false);
    }
  };

  // ---- dataset archive (§6.x) --------------------------------------------

  // Status questions are answered from the UNFILTERED dataset list: a search
  // that hides the selected dataset must not make a frozen one look editable.
  const datasetById = useMemo(() => {
    const map = new Map<string, (typeof datasets)[number]>();
    for (const dataset of datasets) map.set(dataset.dataset_id, dataset);
    return map;
  }, [datasets]);
  const isDatasetFrozen = useCallback(
    (datasetId: string) => {
      const dataset = datasetById.get(datasetId);
      return dataset !== undefined && dataset.status !== 'active';
    },
    [datasetById],
  );
  const datasetName = useCallback(
    (datasetId: string) => datasetById.get(datasetId)?.name ?? null,
    [datasetById],
  );
  const selectedDatasetRecord = selectedDatasetId
    ? (datasetById.get(selectedDatasetId) ?? null)
    : null;

  const canArchiveDataset =
    archiveEnabled &&
    selectedDatasetRecord !== null &&
    selectedDatasetRecord.status === 'active' &&
    selectedDatasetRecord.member_count > 0;

  const datasetArchiveEffectiveRoot = datasetArchiveRoot || archiveRoots[0] || '';
  const datasetArchiveDestination = datasetArchiveEffectiveRoot.replace(/\/+$/, '');
  // The server appends <operator>/<task>/<name> itself (the views shape has
  // one owner); this echo mirrors its sanitisation (views.py) so the dialog
  // cannot promise a path the server would spell differently.
  const sanitizeComponent = (value: string | null | undefined, fallback: string) => {
    const text = (value ?? '').trim().replace(/[/\\\0]/g, '_');
    return text === '' || text === '.' || text === '..' ? fallback : text;
  };
  const datasetArchiveFinalDir =
    datasetArchiveDestination && datasetArchivePath.trim()
      ? `${datasetArchiveDestination}/${datasetArchivePath.trim().replace(/^\/+/, '')}`
      : '';

  // Poll while the selected dataset is archiving — the run is server-owned
  // and this is its only window. 1 s: the same cadence Validation polls jobs.
  const datasetArchiveQuery = useQuery({
    queryKey: queryKeys.datasetArchive(selectedDatasetId ?? ''),
    queryFn: ({ signal }) => getDatasetArchive(selectedDatasetId ?? '', signal),
    enabled: selectedDatasetId !== null && selectedDatasetRecord?.status === 'archiving',
    refetchInterval: 1000,
  });
  const datasetArchiveProgress = datasetArchiveQuery.data ?? null;

  const datasetArchiveMutation = useMutation({
    mutationFn: (vars: { resume: boolean }) =>
      archiveDataset(
        selectedDatasetId ?? '',
        vars.resume
          ? {}
          : {
              destination: datasetArchiveDestination,
              path: datasetArchivePath.trim(),
              mode: datasetArchiveMode,
              reason: datasetArchiveReason.trim() || null,
            },
      ),
    onSuccess: async (progress) => {
      // Seed the poll cache with the 202 body so the dialog flips to its
      // progress view immediately rather than after the first poll.
      queryClient.setQueryData(queryKeys.datasetArchive(progress.dataset_id), progress);
      await invalidateDatasets(progress.dataset_id);
    },
    // Same reasoning as the delete: a run that was refused (gone, already
    // archiving) means this screen's picture of the dataset is out of date.
    onError: () => void invalidateDatasets(selectedDatasetId),
  });

  // Completion is observed, not returned: the 202 started the run, and the
  // poll is what eventually reports `archived`. The toast fires on that edge —
  // whether or not the dialog is still open, because the run kept going either
  // way and the row's badge must follow it.
  const sealedToastRef = useRef<string | null>(null);
  useEffect(() => {
    if (datasetArchiveProgress?.status !== 'archived') return;
    if (sealedToastRef.current === datasetArchiveProgress.dataset_id) return;
    sealedToastRef.current = datasetArchiveProgress.dataset_id;
    setDatasetArchiveOpen(false);
    void invalidateDatasets(datasetArchiveProgress.dataset_id);
    showToast(
      datasetArchiveProgress.mode === 'copy'
        ? `Copied to ${datasetArchiveProgress.destination} — ` +
            `${datasetArchiveProgress.member_total} recording${
              datasetArchiveProgress.member_total === 1 ? '' : 's'
            } verified and sealed; everything stays on this machine`
        : `Archived to ${datasetArchiveProgress.destination} — ` +
            `${datasetArchiveProgress.member_total} recording${
              datasetArchiveProgress.member_total === 1 ? '' : 's'
            } verified, then removed from this machine`,
    );
  }, [datasetArchiveProgress, invalidateDatasets, showToast]);

  // A member shared with another active dataset makes Move refuse, so the
  // dialog opens on Copy when any exist — the combined-set flow — and says
  // why. (The server is the authority; this only picks the default.)
  const datasetArchiveSharedCount = useMemo(() => {
    if (!selectedRow) return 0;
    return selectedRow.members.filter((m) =>
      (m.capture?.memberships ?? []).some(
        (other) =>
          other.dataset_id !== selectedRow.dataset.dataset_id &&
          datasetById.get(other.dataset_id)?.status === 'active',
      ),
    ).length;
  }, [selectedRow, datasetById]);

  const openDatasetArchive = () => {
    setDatasetArchiveOpen(true);
    // Prefilled with the views shape; the operator renames freely from there.
    setDatasetArchivePath(
      selectedDatasetRecord
        ? [
            sanitizeComponent(selectedDatasetRecord.operator, 'unknown_operator'),
            sanitizeComponent(selectedDatasetRecord.task, 'unknown_task'),
            sanitizeComponent(selectedDatasetRecord.name, 'unnamed'),
          ].join('/')
        : '',
    );
    setDatasetArchiveReason('');
    setDatasetArchiveMode(datasetArchiveSharedCount > 0 ? 'copy' : 'move');
    datasetArchiveMutation.reset();
  };
  const cancelDatasetArchive = useCallback(() => setDatasetArchiveOpen(false), []);

  // ---- candidates --------------------------------------------------------

  const memberCaptureIds = useMemo(
    () => new Set(scopeAllMembers.map((row) => row.captureId)),
    [scopeAllMembers],
  );
  const matchedCandidates = useMemo(
    () =>
      captures.filter(
        (capture) =>
          ADDABLE_STATES.has(capture.state) &&
          !memberCaptureIds.has(capture.capture_id) &&
          captureMatches(capture, debouncedCandidateSearch),
      ),
    [captures, memberCaptureIds, debouncedCandidateSearch],
  );
  // Blocked candidates (not adopted, bytes elsewhere) clutter the building
  // flow, so the rail leads with what can actually join — but the blocked
  // count is always stated and one click reveals the rows with their reasons.
  const addableCandidates = useMemo(
    () => matchedCandidates.filter((c) => addBlockedReason(c) === null),
    [matchedCandidates],
  );
  const visibleCandidates = showBlockedCandidates ? matchedCandidates : addableCandidates;

  return {
    rows,
    shown: rows.length,
    total: allRows.length,
    search,
    setSearch,
    sort,
    toggleSort,
    datasetView,
    setDatasetView: (v: 'active' | 'archived') => {
      setDatasetView(v);
      setSelectedMembershipId(null);
    },
    activeDatasetCount: datasets.filter((d) => d.status !== 'archived').length,
    archivedDatasetCount: datasets.filter((d) => d.status === 'archived').length,
    taskResultFilter,
    setTaskResultFilter,
    operatorFilter,
    setOperatorFilter,
    operatorOptions,
    catalogTruncated,

    selectedDatasetId,
    selectedDataset: selectedRow,
    datasetName,
    selectionGone,
    selectDataset,
    isDatasetSelected: (datasetId) => selectedDatasetId === datasetId,
    clearDataset,

    createOpen,
    openCreate: () => setCreateOpen(true),
    cancelCreate: () => setCreateOpen(false),
    newName,
    setNewName,
    newOperator,
    setNewOperator,
    newTask,
    setNewTask,
    submitCreate: () => {
      if (newName.trim()) createMutation.mutate();
    },
    creating: createMutation.isPending,
    createError: createMutation.isError ? createMutation.error : null,

    canEditDataset:
      selectedDatasetRecord !== null && selectedDatasetRecord.status === 'active',
    editOpen,
    openEdit: () => {
      if (!selectedDatasetRecord) return;
      setEditName(selectedDatasetRecord.name);
      setEditOperator(selectedDatasetRecord.operator ?? '');
      setEditTask(selectedDatasetRecord.task ?? '');
      editMutation.reset();
      setEditOpen(true);
    },
    cancelEdit: () => setEditOpen(false),
    editName,
    setEditName,
    editOperator,
    setEditOperator,
    editTask,
    setEditTask,
    submitEdit: () => {
      if (editName.trim()) editMutation.mutate();
    },
    editing: editMutation.isPending,
    editError: editMutation.isError ? editMutation.error : null,

    combineOpen,
    openCombine: () => {
      setCombineSources(selectedDatasetId ? [selectedDatasetId] : []);
      setCombineName('');
      setCombineOperator('');
      setCombineTask('');
      setCombineFailures([]);
      setCombineError(null);
      setCombineDone(0);
      setCombineTotal(0);
      setCombineOpen(true);
    },
    cancelCombine: () => {
      if (!combineBusy) setCombineOpen(false);
    },
    combineChoices: datasets
      .filter((d) => d.status === 'active')
      .map((d) => ({
        datasetId: d.dataset_id,
        name: d.name,
        memberCount: d.member_count,
      })),
    combineSources,
    toggleCombineSource: (datasetId) =>
      setCombineSources((cur) =>
        cur.includes(datasetId)
          ? cur.filter((id) => id !== datasetId)
          : [...cur, datasetId],
      ),
    combineName,
    setCombineName,
    combineOperator,
    setCombineOperator,
    combineTask,
    setCombineTask,
    submitCombine: () => void submitCombine(),
    combineBusy,
    combineDone,
    combineTotal,
    combineFailures,
    combineError,

    confirmingDatasetDelete,
    requestDatasetDelete: () => setConfirmingDatasetDelete(selectedRow !== null),
    cancelDatasetDelete: () => setConfirmingDatasetDelete(false),
    confirmDatasetDelete: () => {
      if (selectedDatasetId) deleteDatasetMutation.mutate(selectedDatasetId);
    },
    deletingDataset: deleteDatasetMutation.isPending,
    datasetDeleteError: deleteDatasetMutation.isError ? deleteDatasetMutation.error : null,

    memberSearch,
    setMemberSearch,
    scopeMembers,
    memberRows,
    memberMatchCount: matchedMembers.length,
    page: currentPage,
    pageCount,
    pageSize: MEMBER_PAGE_SIZE,
    goToPage: (next) => setPage(Math.max(1, next)),
    scope,

    selected,
    selectMember,
    isMemberSelected: (row) => selected?.membershipId === row.membershipId,
    selectSummary,
    isSummaryActive: selected === null,

    detail: captureDetailQuery.data ?? null,
    detailLoading: selected !== null && captureDetailQuery.isPending,
    detailError: selected !== null && captureDetailQuery.isError,

    removeMember: (row) => removeMutation.mutate(row),
    removingMembershipId: removeMutation.isPending ? removeMutation.variables.membershipId : null,

    candidates: visibleCandidates.slice(0, CANDIDATE_LIMIT),
    candidateMatchCount: visibleCandidates.length,
    candidateSearch,
    setCandidateSearch,
    addMember: (capture) => addMutation.mutate(capture),
    addingCaptureId: addMutation.isPending ? addMutation.variables.capture_id : null,
    showBlockedCandidates,
    toggleBlockedCandidates: () => setShowBlockedCandidates((v) => !v),
    blockedCandidateCount: matchedCandidates.length - addableCandidates.length,

    deletion,
    splitDeploy: transferStatusQuery.data?.available === true,

    archiveEnabled,
    archiveRoots,
    canArchive,
    archiveTarget,
    openArchive,
    cancelArchive,
    archiveRoot: effectiveRoot,
    setArchiveRoot,
    archiveSubpath: subpath,
    setArchiveSubpath,
    archiveDestination,
    archiveFinalPath,
    archiveReason,
    setArchiveReason,
    confirmArchive: () => {
      if (archiveTarget) archiveMutation.mutate(archiveTarget);
    },
    archiving: archiveMutation.isPending,
    archiveError: archiveMutation.isError ? archiveMutation.error : null,

    isDatasetFrozen,
    canArchiveDataset,
    datasetArchiveOpen,
    openDatasetArchive,
    cancelDatasetArchive,
    datasetArchiveRoot: datasetArchiveEffectiveRoot,
    setDatasetArchiveRoot,
    datasetArchivePath,
    setDatasetArchivePath,
    datasetArchiveDestination,
    datasetArchiveFinalDir,
    datasetArchiveReason,
    setDatasetArchiveReason,
    datasetArchiveMode,
    setDatasetArchiveMode,
    datasetArchiveSharedCount,
    confirmDatasetArchive: () => {
      if (selectedDatasetId && datasetArchiveDestination && datasetArchivePath.trim()) {
        datasetArchiveMutation.mutate({ resume: false });
      }
    },
    resumeDatasetArchive: () => {
      if (selectedDatasetId) datasetArchiveMutation.mutate({ resume: true });
    },
    datasetArchiveStarting: datasetArchiveMutation.isPending,
    datasetArchiveStartError: datasetArchiveMutation.isError
      ? datasetArchiveMutation.error
      : null,
    datasetArchiveProgress,

    isLoading: listQuery.isPending || capturesQuery.isPending,
    isError: listQuery.isError || capturesQuery.isError,

    toast,
    blockingFailure,
    dismissBlockingFailure: () => setBlockingFailure(null),
  };
}
